mkdir -p /work && cat > /work/quickstart.mjs <<'EOF'
// Generate an AES-256 key from Qrypt quantum entropy.
// Run with: qrypt-run quickstart.mjs
import { readFileSync } from "node:fs";
import { webcrypto as crypto } from "node:crypto";

const ENTROPY_URL = "https://api-eus.qrypt.com/api/v1/quantum-entropy?size=1"; // size is in KiB

function loadToken() {
  if (process.env.QRYPT_API_KEY) return process.env.QRYPT_API_KEY.trim();
  const env = readFileSync(new URL("./.env", import.meta.url), "utf8");
  for (const line of env.split(/\r?\n/)) {
    const m = line.match(/^\s*(?:export\s+)?QRYPT_API_KEY\s*=\s*(.*)\s*$/);
    if (m) return m[1].replace(/^(['"])(.*)\1$/, "$2").trim();
  }
  throw new Error("QRYPT_API_KEY not found in environment or .env");
}

const ERRORS = {
  400: "size must be between 1 and 512 KiB",
  401: "Authorization header missing, malformed, or expired",
  403: "token invalid or monthly quota exhausted",
  429: "rate limited; wait at least 10 seconds before retrying",
  500: "Qrypt service error; try again later",
  503: "Qrypt service busy; try again later",
};

async function fetchQuantumEntropy() {
  const res = await fetch(ENTROPY_URL, {
    headers: {
      Authorization: `Bearer ${loadToken()}`,
      Accept: "application/json",
      "User-Agent": "qrypt-aes256-quickstart/1.0",
    },
  });
  if (!res.ok) throw new Error(`Qrypt API ${res.status}: ${ERRORS[res.status] ?? res.statusText}`);
  const body = await res.json();
  if (!Array.isArray(body.random) || !body.random.length) throw new Error("Unexpected response: no 'random' array");
  return Buffer.from(body.random[0], "base64");
}

export async function generateAes256Key() {
  const entropy = await fetchQuantumEntropy();
  if (entropy.length < 32) throw new Error(`Only ${entropy.length} bytes of entropy returned`);
  const raw = new Uint8Array(entropy.subarray(0, 32));
  entropy.fill(0);
  const key = await crypto.subtle.importKey("raw", raw, { name: "AES-GCM" }, false, ["encrypt", "decrypt"]);
  raw.fill(0);
  return key;
}

// Demo: generate a key and verify it with an AES-256-GCM round trip.
// The key itself is never printed or written to disk.
const key = await generateAes256Key();
const nonce = crypto.getRandomValues(new Uint8Array(12)); // fresh 12-byte nonce per encryption
const plaintext = new TextEncoder().encode("Hello from Qrypt quantum entropy!");
const ciphertext = await crypto.subtle.encrypt({ name: "AES-GCM", iv: nonce }, key, plaintext);
const decrypted = new TextDecoder().decode(await crypto.subtle.decrypt({ name: "AES-GCM", iv: nonce }, key, ciphertext));

console.log(`Generated ${key.algorithm.name} key, ${key.algorithm.length} bits (non-extractable)`);
console.log(`Ciphertext+tag: ${ciphertext.byteLength} bytes`);
console.log(`Round trip OK: ${decrypted === "Hello from Qrypt quantum entropy!"}`);
EOF
cat > /work/package.json <<'EOF'
{
  "name": "qrypt-aes256-quickstart",
  "version": "1.0.0",
  "private": true,
  "type": "module",
  "scripts": { "start": "qrypt-run quickstart.mjs" }
}
EOF
printf '.env\nnode_modules/\n' > /work/.gitignore
cd /work && qrypt-run quickstart.mjs

